    PROPOSAL_NOT_FOUND: "Run `akm proposal list` to see pending proposals and their ids.",
    FILE_NOT_FOUND: "Check the path exists and is readable.",
    IMPROVE_RUN_NOT_FOUND: "Run `akm improve` first, or `akm doctor metrics improve --since 30d` to see recent run ids in `runIds`.",
    REGISTRY_NOT_FOUND: "Check the ref's spelling and version; `akm search <query> --from registry` lists installable refs.",
